'use strict';
const $=s=>document.querySelector(s);
const paths={back:'M19 12H5m7-7-7 7 7 7',menu:'M4 6h16M4 12h16M4 18h16',cursor:'m4 3 7 18 2-8 8-2L4 3Z',hand:'M8 13V5a2 2 0 0 1 4 0v6-8a2 2 0 0 1 4 0v8-5a2 2 0 0 1 4 0v9c0 4-3 6-7 6h-1c-2 0-4-1-5-3l-4-6a2 2 0 0 1 3-2l2 3',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Zm8-2v4m-2-2h4',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',brief:'M6 3h9l4 4v14H5V3h1Zm8 0v5h5M8 12h8m-8 4h6',chat:'M4 4h16v12H9l-5 4V4Z',undo:'M9 4 4 9l5 5M4 9h10a6 6 0 0 1 0 12',redo:'m15 4 5 5-5 5m5-5H10a6 6 0 0 0 0 12',plus:'M12 5v14M5 12h14',minus:'M5 12h14',close:'m6 6 12 12M6 18 18 6',chevron:'m8 5 7 7-7 7',check:'m5 12 4 4L19 6',share:'M12 16V3m-5 5 5-5 5 5M5 13v7h14v-7',link:'m10 14 4-4m-6 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m-1-1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1s-1 6 1 8l7 7 7-7c2-2 4-5 1-8Z',business:'M3 8h18v13H3zM8 8V4h8v4M3 13h18m-9-2v4',bolt:'m13 2-9 12h7l-1 8 10-13h-8l1-7Z',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',wild:'m12 2 2 6 6-2-2 6 4 4-7 1-3 5-3-5-7-1 4-4-2-6 6 2 2-6Z',rotate:'M20 8a8 8 0 1 0 0 8M20 3v5h-5',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4m0 3v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',pencil:'m4 16 12-12 4 4L8 20l-5 1 1-5Zm10-10 4 4',text:'M4 4h16M12 4v17m-5 0h10',section:'M3 8V3h5m8 0h5v5M3 16v5h5m8 0h5v-5',send:'m4 11 8-8 8 8M12 3v18',bulb:'M8 15a7 7 0 1 1 8 0l-1 3H9l-1-3Zm1 6h6',file:'M5 3h9l5 5v13H5V3Zm9 0v6h5',image:'M3 3h18v18H3zM3 17l6-6 4 4 3-3 5 5M15 7h.01',more:'M5 12h.01M12 12h.01M19 12h.01',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM12 6v6l4 2'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`}
const cube=(size=30)=>`<svg width="${size}" height="${size}" viewBox="0 0 32 36" aria-hidden="true"><path fill="#a7bcff" d="m16 1 15 8-15 9L1 9Z"/><path fill="#708aff" d="m1 9 15 9v17L1 26Z"/><path fill="#4e59e9" d="m16 18 15-9v17l-15 9Z"/><path stroke="#fff" stroke-opacity=".7" stroke-width="1.2" fill="none" d="m1 9 15 9 15-9M16 18v17"/></svg>`;
const faces=[{id:'user',label:'User',zh:'User',icon:'user',color:'#daeaff'},{id:'emotion',label:'Emotion',zh:'Emotion',icon:'heart',color:'#fbe0e9'},{id:'business',label:'Business',zh:'Business',icon:'business',color:'#ffe6c5'},{id:'tech',label:'Tech',zh:'Tech',icon:'bolt',color:'#e9dfff'},{id:'constraint',label:'Constraint',zh:'Constraint',icon:'lock',color:'#e8ebf0'},{id:'wildcard',label:'Wildcard',zh:'Wildcard',icon:'wild',color:'#e1f2d3'}];
const blankBoard=()=>({id:crypto.randomUUID(),version:2,stage:0,title:'Untitled board',goal:'',audience:'',hmws:[],notes:[],attachments:[],axis:'impact',mapPlaced:false,updatedAt:Date.now()});
const storagePrefix=window.cubeDemo?'cube-demo-':'cube-';
const storageKeys={index:storagePrefix+'board-index-v2',active:storagePrefix+'active-board-v2',board:id=>storagePrefix+'board-v2:'+id};
const initial=window.cubeDemo?{...blankBoard(),...structuredClone(window.cubeDemo)}:blankBoard();
let state=structuredClone(initial),face='user',selected=null,sidebarOpen=false,panelOpen=innerWidth>850,zoom=1,pan={x:0,y:0},tool='cursor',history=[],future=[],suggestion=null,chat=[],storageOk=true,boardIndex=[];
try{const storedIndex=localStorage.getItem(storageKeys.index);boardIndex=JSON.parse(storedIndex||'[]');const active=localStorage.getItem(storageKeys.active);const saved=active&&JSON.parse(localStorage.getItem(storageKeys.board(active)));if(saved&&saved.version===2&&Array.isArray(saved.notes)&&Array.isArray(saved.hmws))state=saved;else if(window.cubeDemo&&storedIndex!==null)state=blankBoard()}catch(e){}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const faceBy=id=>faces.find(f=>f.id===id)||faces[0];
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function save(){state.updatedAt=Date.now();try{localStorage.setItem(storageKeys.board(state.id),JSON.stringify(state));localStorage.setItem(storageKeys.active,state.id);boardIndex=boardIndex.filter(b=>b.id!==state.id);boardIndex.unshift({id:state.id,title:state.title,updatedAt:state.updatedAt});localStorage.setItem(storageKeys.index,JSON.stringify(boardIndex));storageOk=true}catch(e){storageOk=false;toast('Not saved: device storage is full. Export your board to keep it.')}const status=$('.save-status');if(status)status.innerHTML=icon(storageOk?'check':'help',11)+(storageOk?'Saved on this device':'Not saved — export a copy')}
function snapshot(){history.push(JSON.stringify(state));if(history.length>40)history.shift();future=[]}
function render(){
enforceWorkflow();
const stages=['Context','Decompose','Ideate','2×2 Map'];
const header=`<header class="topbar"><div class="top-left"><button class="icon-btn navigation-toggle" id="navigation-toggle" data-action="toggle-navigation" aria-label="Open navigation" aria-expanded="false" aria-controls="stage-sidebar">${icon('menu',21)}</button><button class="brand" data-action="boards" aria-label="Your boards">${cube(26)}<span>cube<small>.ai</small></span></button></div><div class="header-project"><button type="button" id="project-title-label" class="project-title-label" title="Rename project" aria-label="Rename project: ${esc(state.title==='Untitled board'?'Untitled project':state.title)}">${esc(state.title==='Untitled board'?'Untitled project':state.title)}</button><input id="header-project-title" class="header-project-title" aria-label="Project name" value="${esc(state.title==='Untitled board'?'':state.title)}" placeholder="Untitled project" maxlength="80" autocomplete="off" spellcheck="false" hidden></div><div class="top-right">${state.stage<2?`<button class="btn context-help" data-action="help">${icon('help',15)}Help</button>`:`<span class="avatar" title="You · Guest Otter">🦦</span><button class="btn" data-action="share">${icon('share',15)}Share</button><button class="btn primary" data-action="summary">Export</button>`}</div></header>`;
const navigation=`<button class="sidebar-backdrop" id="sidebar-backdrop" data-action="close-navigation" aria-label="Close navigation" tabindex="-1" hidden></button><aside class="stage-sidebar" id="stage-sidebar" hidden><nav class="stage-navigation" aria-label="Brainstorming stages">${stages.map((s,i)=>`<button class="stage-link ${state.stage===i?'active':''}" data-stage="${i}" ${stageGateAttributes(i)} aria-current="${state.stage===i?'step':'false'}"><span class="stage-number">${i+1}</span><span>${s}</span><span class="stage-lock" ${workflowBlocker(i)?'':'hidden'}>${icon('lock',14)}</span></button>`).join('')}</nav><p id="workflow-nav-hint" class="workflow-nav-hint"></p></aside>`;
const content=state.stage<2?`<main class="context-page ${state.stage===1?'decompose-page':''}"><section class="context-viewport" id="viewport" aria-label="${state.stage===0?'Project context':'Project questions'}"></section><input type="file" id="file-input" accept="image/*,application/pdf" multiple hidden></main>`:`<main class="workarea ${panelOpen?'':'panel-hidden'}"><div class="rail" role="group" aria-label="Board controls"><button class="icon-btn" data-action="undo" aria-label="Undo">${icon('undo',17)}</button><button class="icon-btn" data-action="redo" aria-label="Redo">${icon('redo',17)}</button><div class="rail-sep"></div><button class="icon-btn" data-action="help" aria-label="Help & shortcuts">${icon('help',17)}</button></div><div class="canvas-actions${state.stage===3?' map-actions':''}">${state.stage===2&&state.notes.length?`<button class="btn small" data-action="cluster">${icon('grid',13)}Tidy up</button><button class="btn small" data-stage="3">${icon('section',13)}2×2 Map</button>`:state.stage===3?`<button class="btn small map-back" data-stage="2">${icon('back',14)}Back to Ideate</button><select class="axis-select" id="axis" aria-label="Map axes"><option value="impact" ${state.axis==='impact'?'selected':''}>Impact × Effort</option><option value="novelty" ${state.axis==='novelty'?'selected':''}>Novelty × Feasibility</option><option value="value" ${state.axis==='value'?'selected':''}>User × Business value</option></select><button class="btn small" data-action="place">${icon('grid',13)}Arrange rated</button>`:''}</div><section class="board-viewport ${state.stage<2?'form-view':''}" id="viewport" aria-label="${stages[state.stage]} canvas"></section><aside class="cube-panel" id="cube-companion-panel" aria-label="Cube Companion"><div class="panel-head"><div class="cube-avatar">${cube(24)}</div><div><h2>Cube</h2><small>Your thinking companion</small></div><button class="icon-btn" data-action="toggle-panel" aria-label="Close Cube Companion" aria-controls="cube-companion-panel">${icon('close',16)}</button></div><div class="panel-scroll" id="panel-content"></div><div class="panel-bottom"><form class="ask-box" id="ask-form"><input id="ask-input" aria-label="Ask Cube a question" placeholder="Ask Cube anything…" autocomplete="off"><button aria-label="Send question">${icon('send',15)}</button></form><div class="prototype-note">Your ideas. Your judgment.</div></div></aside>${!panelOpen?`<button class="panel-reopen btn soft" data-action="toggle-panel" aria-label="Open Cube Companion · Q" aria-expanded="false" aria-controls="cube-companion-panel" aria-keyshortcuts="Q">${icon('spark',16)}<span>Ask Cube</span><kbd class="key-hint">Q</kbd></button>`:''}<div class="canvas-hint">Double-click to edit · Drag to arrange · Hold space to pan</div><div class="bottom-tools" aria-label="Canvas toolbar"><button class="tool ${tool==='cursor'?'active':''}" data-tool="cursor" aria-label="Select · V">${icon('cursor',21)}</button><button class="tool ${tool==='hand'?'active':''}" data-tool="hand" aria-label="Pan · H">${icon('hand',21)}</button><div class="tool-sep"></div><div class="sticky-tools">${faces.map(f=>`<button class="sticky-tool" style="background:${f.color}" data-add="${f.id}" aria-label="Add ${f.zh} sticky note"></button>`).join('')}</div><div class="tool-sep"></div><button class="tool extra" data-action="new-board" aria-label="New blank board">${icon('plus',20)}</button><button class="tool companion-toggle ${panelOpen?'is-open':'is-closed'}" data-action="toggle-panel" aria-label="${panelOpen?'Close':'Open'} Cube Companion · Q" aria-expanded="${panelOpen}" aria-controls="cube-companion-panel" aria-keyshortcuts="Q">${icon('spark',21)}</button></div><div class="zoom-control"><button class="icon-btn" data-action="zoom-out" aria-label="Zoom out">${icon('minus',14)}</button><button class="zoom-label" data-action="fit" aria-label="Fit canvas">100%</button><button class="icon-btn" data-action="zoom-in" aria-label="Zoom in">${icon('plus',14)}</button><button class="icon-btn" data-action="fit" aria-label="Fit to view">${icon('expand',13)}</button></div><div class="touch-tip">Pinch to zoom · Drag to pan</div><input type="file" id="file-input" accept="image/*,application/pdf" multiple hidden></main>`;
$('#app').innerHTML=header+navigation+content;
renderBoard();if(state.stage>=2)renderPanel();bind();updateWorkflowControls();setSidebarOpen(sidebarOpen,false);if(state.stage>=2)requestAnimationFrame(fit);
}
function noteMarkup(n,map=false){const f=faceBy(n.face);return `<article class="note ${n.face} ${selected===n.id?'selected':''} ${map?'map-note':''}" data-note="${n.id}" tabindex="0" role="button" aria-label="${esc(n.text)}" style="left:${n.x}px;top:${n.y}px;transform:rotate(${map?0:(Number(n.id.replace(/\D/g,''))%3-1)*.6}deg)"><div class="note-tag">${icon(f.icon,11)}${f.label}</div><div class="note-text">${esc(n.text)}</div><div class="note-foot"><span>${n.author==='Cube'?'✧ Cube · Starter idea':'🦦 You'}</span><button class="note-like ${n.liked?'liked':''}" data-like="${n.id}" aria-label="Like this idea">👍 ${n.likes||0}</button></div></article>`}
function applyTransform(){const w=$('#world');if(w)w.style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`;if($('.zoom-label'))$('.zoom-label').textContent=Math.round(zoom*100)+'%'}
